import{_ as e,o,c as d,a2 as a}from"./chunks/framework.C9xbT7QL.js";const u=JSON.parse('{"title":"Integration Overview","description":"All hookshot integrations and their capabilities at a glance","frontmatter":{"title":"Integration Overview","description":"All hookshot integrations and their capabilities at a glance","audience":["evaluator","user","operator","developer","architect"]},"headers":[],"relativePath":"integrations/overview.md","filePath":"integrations/overview.md","lastUpdated":1775244648000}'),r={name:"integrations/overview.md"};function n(s,t,i,c,h,p){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="integration-overview" tabindex="-1">Integration Overview <a class="header-anchor" href="#integration-overview" aria-label="Permalink to &quot;Integration Overview&quot;">​</a></h1><p>Hookshot connects Matrix rooms to external services through <strong>connections</strong> — bidirectional bindings stored as Matrix room state events. Each connection type handles events from one external service and optionally accepts commands from Matrix.</p><h2 id="capability-matrix" tabindex="-1">Capability Matrix <a class="header-anchor" href="#capability-matrix" aria-label="Permalink to &quot;Capability Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Integration</th><th>Inbound events</th><th>Outbound commands</th><th>OAuth</th><th>Webhooks</th><th>Bot commands</th><th>Widget UI</th><th>Provisioning API</th></tr></thead><tbody><tr><td><a href="#github">GitHub</a></td><td>23 event types</td><td>Create, close, assign issues; trigger workflows</td><td>Yes (GitHub App + user OAuth)</td><td>Yes</td><td><code>!gh</code></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="#gitlab">GitLab</a></td><td>12 event types</td><td>Create, close issues</td><td>Yes (token-based)</td><td>Yes</td><td><code>!gl</code></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="#jira">JIRA</a></td><td>5 event types</td><td>Create, assign issues</td><td>Yes (Cloud: OAuth 2.0, Server: OAuth 1.0)</td><td>Yes</td><td><code>!jira</code></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="#generic-webhooks">Generic Webhooks</a></td><td>Any JSON/form/XML payload</td><td>Outbound hooks (separate connection)</td><td>No</td><td>Yes</td><td>Via <code>!hookshot webhook</code></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="#feeds">RSS/Atom Feeds</a></td><td>New feed entries</td><td>None</td><td>No</td><td>No (polling)</td><td>Via <code>!hookshot feed</code></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="#figma">Figma</a></td><td>File comments</td><td>None</td><td>No</td><td>Yes</td><td>Via <code>!hookshot figma file</code></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="#openproject">OpenProject</a></td><td>Work packages created/updated</td><td>Create, close, assign, set priority</td><td>Yes (OAuth 2.0)</td><td>Yes</td><td><code>!op</code></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="#challengehound">ChallengeHound</a></td><td>Activities</td><td>None</td><td>No</td><td>No (polling)</td><td>Via <code>!hookshot challenghound</code></td><td>Yes</td><td>Yes</td></tr></tbody></table><h2 id="connection-types-per-service" tabindex="-1">Connection types per service <a class="header-anchor" href="#connection-types-per-service" aria-label="Permalink to &quot;Connection types per service&quot;">​</a></h2><p>Some services have multiple connection types for different use cases.</p><table tabindex="0"><thead><tr><th>Service</th><th>Connection type</th><th>State event</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>GitHub</strong></td><td>GitHubRepoConnection</td><td><code>uk.half-shot.matrix-hookshot.github.repository</code></td><td>Monitor repo events, run commands</td></tr><tr><td></td><td>GitHubIssueConnection</td><td><code>uk.half-shot.matrix-hookshot.github.issue</code></td><td>Bridge a single issue to a room</td></tr><tr><td></td><td>GitHubDiscussionConnection</td><td><code>uk.half-shot.matrix-hookshot.github.discussion</code></td><td>Bridge a discussion thread</td></tr><tr><td></td><td>GitHubDiscussionSpace</td><td><code>uk.half-shot.matrix-hookshot.github.discussion.space</code></td><td>Space for all repo discussions</td></tr><tr><td></td><td>GitHubProjectConnection</td><td><code>uk.half-shot.matrix-hookshot.github.project</code></td><td>Monitor a project board</td></tr><tr><td></td><td>GitHubUserSpace</td><td><code>uk.half-shot.matrix-hookshot.github.user.space</code></td><td>Space for user notifications</td></tr><tr><td><strong>GitLab</strong></td><td>GitLabRepoConnection</td><td><code>uk.half-shot.matrix-hookshot.gitlab.repository</code></td><td>Monitor project events, run commands</td></tr><tr><td></td><td>GitLabIssueConnection</td><td><code>uk.half-shot.matrix-hookshot.gitlab.issue</code></td><td>Bridge a single issue to a room</td></tr><tr><td><strong>JIRA</strong></td><td>JiraProjectConnection</td><td><code>uk.half-shot.matrix-hookshot.jira.project</code></td><td>Monitor project events, run commands</td></tr><tr><td><strong>Webhooks</strong></td><td>GenericHookConnection</td><td><code>uk.half-shot.matrix-hookshot.generic.hook</code></td><td>Receive any HTTP webhook</td></tr><tr><td></td><td>OutboundHookConnection</td><td><code>uk.half-shot.matrix-hookshot.outbound-hook</code></td><td>Forward Matrix messages to external URL</td></tr><tr><td><strong>Feeds</strong></td><td>FeedConnection</td><td><code>uk.half-shot.matrix-hookshot.feed</code></td><td>Poll RSS/Atom feed</td></tr><tr><td><strong>Figma</strong></td><td>FigmaFileConnection</td><td><code>uk.half-shot.matrix-hookshot.figma.file</code></td><td>Receive file comments</td></tr><tr><td><strong>OpenProject</strong></td><td>OpenProjectConnection</td><td><code>org.matrix.matrix-hookshot.openproject.project</code></td><td>Monitor work packages, run commands</td></tr><tr><td><strong>ChallengeHound</strong></td><td>HoundConnection</td><td><code>uk.half-shot.matrix-hookshot.challengehound.activity</code></td><td>Receive activities</td></tr></tbody></table><h2 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h2><p>GitHub is the most feature-rich integration, with 6 connection types covering repositories, issues, discussions, projects, and user notifications.</p><p><strong>Inbound events (GitHubRepoConnection):</strong> Issue created/edited/closed/labeled, issue comments, PR opened/closed/merged/reviewed/ready-for-review, pushes, releases, workflow runs. 23 configurable event types, 13 enabled by default.</p><p><strong>Outbound commands:</strong> <code>!gh create</code>, <code>!gh close</code>, <code>!gh assign</code>, <code>!gh workflow run</code></p><p><strong>Emoji reactions:</strong> Matrix emoji reactions map to GitHub reactions. Trash emoji closes issues, checkmark approves PRs.</p><p><strong>Auth:</strong> GitHub App (required for webhooks) + optional user OAuth for per-user actions.</p><h2 id="gitlab" tabindex="-1">GitLab <a class="header-anchor" href="#gitlab" aria-label="Permalink to &quot;GitLab&quot;">​</a></h2><p>Monitors GitLab projects for merge requests, issues, pushes, tags, wiki changes, and releases.</p><p><strong>Inbound events (GitLabRepoConnection):</strong> MR opened/closed/merged/approved/updated, MR comments, issue comments, releases, tag pushes, pushes, wiki page events. 12 handler bindings.</p><p><strong>Outbound commands:</strong> <code>!gl create</code>, <code>!gl create-confidential</code>, <code>!gl close</code></p><p><strong>Auth:</strong> Personal access token or OAuth token configured per-instance.</p><h2 id="jira" tabindex="-1">JIRA <a class="header-anchor" href="#jira" aria-label="Permalink to &quot;JIRA&quot;">​</a></h2><p>Monitors JIRA projects for issue creation, updates, and version events. Supports both JIRA Cloud (OAuth 2.0) and JIRA Server/Data Center (OAuth 1.0).</p><p><strong>Inbound events:</strong> Issue created, issue updated, version created/updated/released.</p><p><strong>Outbound commands:</strong> <code>!jira create</code>, <code>!jira issue-types</code>, <code>!jira assign</code></p><p><strong>Auth:</strong> JIRA Cloud uses OAuth 2.0 via <code>auth.atlassian.com</code>. JIRA Server uses OAuth 1.0 with RSA-SHA1.</p><h2 id="generic-webhooks" tabindex="-1">Generic Webhooks <a class="header-anchor" href="#generic-webhooks" aria-label="Permalink to &quot;Generic Webhooks&quot;">​</a></h2><p>Accepts arbitrary HTTP payloads and delivers them to Matrix rooms. Supports JSON, URL-encoded forms, XML, and plain text.</p><p><strong>Inbound:</strong> Any HTTP POST to a unique webhook URL (<code>/webhook/{hookId}</code>).</p><p><strong>Transformation functions:</strong> Optional JavaScript functions (executed in a QuickJS sandbox) that transform the raw payload into a custom Matrix message. Supports v1 and v2 transformation APIs.</p><p><strong>Outbound hooks:</strong> A separate <code>OutboundHookConnection</code> forwards Matrix room messages to an external HTTP endpoint.</p><p><strong>No service-specific auth.</strong> Webhook URLs contain a unique UUID and can optionally be protected with secrets.</p><h2 id="feeds" tabindex="-1">Feeds <a class="header-anchor" href="#feeds" aria-label="Permalink to &quot;Feeds&quot;">​</a></h2><p>Polls RSS and Atom feeds at regular intervals and posts new entries to Matrix rooms.</p><p><strong>Polling:</strong> Uses a Rust-based feed parser. Supports ETag/Last-Modified caching and exponential backoff.</p><p><strong>Message templates:</strong> Customizable with tokens: <code>$FEEDNAME</code>, <code>$TITLE</code>, <code>$LINK</code>, <code>$AUTHOR</code>, <code>$DATE</code>, <code>$SUMMARY</code>. Default template: <code>&quot;New post in $FEEDNAME: $LINK&quot;</code>.</p><p><strong>Error handling:</strong> Optional failure notifications when feed polling fails. Last 5 poll results stored for diagnostics.</p><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p>Receives Figma file comment webhooks and posts them to Matrix rooms.</p><p><strong>Inbound:</strong> FILE_COMMENT events only. Other Figma webhook types (FILE_UPDATE, LIBRARY_PUBLISH) are not currently handled.</p><p><strong>Auth:</strong> Figma API token configured per-instance.</p><h2 id="openproject" tabindex="-1">OpenProject <a class="header-anchor" href="#openproject" aria-label="Permalink to &quot;OpenProject&quot;">​</a></h2><p>Monitors OpenProject instances for work package creation and updates. Supports OAuth 2.0 with automatic token refresh.</p><p><strong>Inbound events:</strong> Work package created, work package updated.</p><p><strong>Outbound commands:</strong> <code>!op create</code>, <code>!op close</code>, <code>!op priority</code>, <code>!op assign</code>, <code>!op responsible</code></p><h2 id="challengehound" tabindex="-1">ChallengeHound <a class="header-anchor" href="#challengehound" aria-label="Permalink to &quot;ChallengeHound&quot;">​</a></h2><p>Receives activity updates from ChallengeHound challenges.</p><p><strong>Inbound:</strong> Activity events (polling-based, not webhook).</p><h2 id="how-connections-are-created" tabindex="-1">How connections are created <a class="header-anchor" href="#how-connections-are-created" aria-label="Permalink to &quot;How connections are created&quot;">​</a></h2><p>Four ways to create a connection in a room:</p><ol><li><strong>Bot commands</strong> — <code>!hookshot {service} {args}</code> in a Matrix room</li><li><strong>Widget UI</strong> — Embedded web interface in Matrix clients</li><li><strong>Provisioning API</strong> — REST API at <code>/widgetapi/v1/{roomId}/connections/{type}</code></li><li><strong>Static config</strong> — Pre-defined connections in <code>config.yml</code></li><li><strong>Direct state events</strong> — Set Matrix room state events directly</li></ol><p>The <code>SetupConnection</code> handles bot commands for creating connections across all services. It supports 18+ setup commands.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Concepts:</strong> <a href="./../understand/event-lifecycle">Event Lifecycle</a> · <a href="./../understand/integration-model">Integration Model</a> · <a href="./../understand/trust-and-boundaries">Trust and Boundaries</a></p><p><strong>Architecture:</strong> <a href="./../architecture/connections">Connections</a> — Connection lifecycle and internals</p><p><strong>Reference:</strong> <a href="./../reference/bot-commands">Bot Commands</a> · <a href="./../reference/event-types">Event Types</a> · <a href="./../reference/matrix-spec-map">Matrix Spec Map</a></p><p><strong>Guides:</strong> <a href="./../guides/operator/configuration">Configuration</a> — Service-specific config sections</p><p><strong>Get started:</strong> <a href="./../get-started/quickstart">Quickstart</a> · <a href="./../get-started/evaluate">Evaluate</a></p>',55)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
